const defaultState={current:'Robby',portfolio:'Robby',progress:[],entries:[],drafts:{},customLessons:[]};
let state=loadState();let currentSubject='reading';let currentLesson=null;let speech=null;
function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem('starbound-state')||'{}')}}catch{return {...defaultState}}}
function saveState(){localStorage.setItem('starbound-state',JSON.stringify(state))}
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function today(){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date())}
function updateHeader(){const p=$('#profileButton');p.innerHTML=`<span class="mini-avatar">${state.current[0]}</span>${state.current}⌄`;$('#todayLabel').textContent=`Today · ${today()}`;$('#learnerNote').textContent=state.current==='Robby'?'Sound it out, test an idea, and collect a star.':'Race through a story, find the hidden structure, and prove your thinking.';$('#orbCount').textContent=state.progress.filter(x=>x.learner===state.current).length}
function setView(name){$$('.view').forEach(v=>v.classList.remove('active'));$(`#${name}View`).classList.add('active');$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='log')renderLog();if(name==='portfolio')renderPortfolio();scrollTo({top:0,behavior:'smooth'})}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
$('#profileButton').addEventListener('click',()=>$('#profileDialog').showModal());$$('[data-profile]').forEach(b=>b.addEventListener('click',()=>{state.current=b.dataset.profile;saveState();updateHeader();if($('#subjectView').classList.contains('active'))openSubject(currentSubject)}));
$$('[data-subject]').forEach(b=>b.addEventListener('click',()=>openSubject(b.dataset.subject)));
function lessonsFor(learner,subject){return [...LESSONS[learner][subject],...state.customLessons.filter(l=>l.learner===learner&&l.subject===subject)]}
function openSubject(subject){currentSubject=subject;const s=SUBJECTS[subject];$('#subjectKicker').textContent=s.kicker;$('#subjectTitle').textContent=s.title;$('#subjectIntro').textContent=s.intro;$('#subjectGlyph').textContent=s.glyph;$('#subjectGlyph').style.background=`${s.color}22`;const lessons=lessonsFor(state.current,subject);$('#lessonGrid').innerHTML=lessons.map((l,i)=>{const done=state.progress.some(p=>p.learner===state.current&&p.lessonId===l.id);return `<button class="lesson-card" style="--accent:${s.color}" data-lesson="${l.id}"><span class="number">${i+1}</span><h2>${esc(l.title)}</h2><p>${esc(l.desc)}</p><footer><span>${esc(l.skill.split('·')[0])}</span><span class="${done?'done-stamp':''}">${done?'✓ complete':'start ›'}</span></footer></button>`}).join('');$$('[data-lesson]').forEach(b=>b.addEventListener('click',()=>openLesson(b.dataset.lesson)));setView('subject')}
function findLesson(id){return [...Object.values(LESSONS[state.current]).flat(),...state.customLessons.filter(l=>l.learner===state.current)].find(l=>l.id===id)}
function openLesson(id){currentLesson=findLesson(id);const l=currentLesson;let body='';if(l.type==='reader')body=readerTemplate(l);if(l.type==='blend')body=blendTemplate(l);if(l.type==='choice')body=choiceTemplate(l);if(l.type==='writing')body=writingTemplate(l);if(l.type==='compare')body=compareTemplate(l);if(l.type==='equation')body=equationTemplate(l);if(l.type==='force')body=forceTemplate(l);if(l.type==='music')body=musicTemplate(l);if(l.type==='spanish')body=spanishTemplate(l);if(l.type==='custom')body=customTemplate(l);$('#lessonContent').innerHTML=`<div class="lesson-shell"><button class="dialog-close" data-close="lessonDialog">×</button><p class="soft-label">${SUBJECTS[currentSubject].kicker} mission</p><h2>${esc(l.title)}</h2><p class="skill">Target: ${esc(l.skill)}</p><div class="lesson-body">${body}</div><div class="lesson-footer"><span id="answerStatus">Try it, explain it, then log it.</span><button class="complete-btn" id="completeLesson">Complete mission +1 ✦</button></div></div>`;bindLesson();$('#lessonDialog').showModal();if(l.type==='force')window.dispatchEvent(new CustomEvent('starbound:lab',{detail:{type:l.type}}))}
function readerTemplate(l){const words=l.data.text.split(/(\s+)/).map((w,i)=>/^\s+$/.test(w)?w:`<span data-word="${i}">${esc(w)}</span>`).join('');return `<div class="read-controls"><button id="readAloud">▶ Read with natural voice</button><button id="stopRead">■ Stop</button><label>English voice <select id="voiceSelect" aria-label="Natural English read-aloud voice"><option value="auto">Best natural English voice</option></select></label></div><p class="voice-note">The best enhanced or premium English voice installed on this device is selected automatically.</p><div class="reader-text" id="readerText" data-plain="${esc(l.data.text)}">${words}</div>${questionBlock(l.data)}`}
function blendTemplate(l){return `<p>${l.data.question}</p><div class="blend-board">${l.data.parts.map((p,i)=>`<button class="sound-chip" data-sound="${p}">${p}</button>${i<l.data.parts.length-1?'<span class="operator">+</span>':''}`).join('')}<span class="operator">=</span><button class="sound-chip" data-sound="${l.data.word}">?</button></div><div class="choices"><button class="choice" data-answer="true">${l.data.word}</button><button class="choice" data-answer="false">ran</button></div>`}
function questionBlock(d){return `<p><b>${d.q}</b></p><div class="choices">${d.choices.map((c,i)=>`<button class="choice" data-answer="${i===d.answer}">${esc(c)}</button>`).join('')}</div>`}
function choiceTemplate(l){return `<div class="reader-text">${esc(l.data.text)}</div>${questionBlock(l.data)}`}
function writingTemplate(l){return `<p><b>${l.data.prompt}</b></p><textarea class="writing-box" id="writingDraft" placeholder="${esc(l.data.starter)}">${esc(state.drafts[l.id]||'')}</textarea><div class="checklist">${l.data.checks.map(c=>`<label><input type="checkbox"> ${c}</label>`).join('')}</div><button class="lesson-action" id="saveDraft">Save writing sample</button>`}
function compareTemplate(l){const opts=l.data.advanced?['A = B + C','A + B = C','A = B - C']:['<','=','>'];return `<p><b>${l.data.q}</b></p><div class="math-bars"><div class="bar a">${l.data.advanced?'A':''}</div><div class="bar b">${l.data.advanced?'B':''}</div><div class="symbol-buttons">${opts.map(x=>`<button class="choice" data-value="${x}" data-answer="${x===l.data.answer}">${x}</button>`).join('')}</div></div>`}
function equationTemplate(l){return `<p><b>${l.data.q}</b></p><label>Your answer <input id="numberAnswer" type="number" inputmode="numeric"></label> <button class="lesson-action" id="checkNumber">Check relationship</button>`}
function forceTemplate(){return `<p>Predict first: how will a stronger push change the ball's motion?</p><div class="force-lab"><canvas class="three-stage" id="lab3d" aria-label="Interactive 3D force experiment"></canvas><label>Push strength <input id="forceRange" type="range" min="1" max="5" value="1"></label><button class="lesson-action" id="testForce">Test push</button><p id="forceResult">Set a strength and run the test.</p></div>`}
function musicTemplate(l){const seed=['C4','E4','G4','E4'];return `<div class="music-guide"><b>Mission:</b> Move the notes. Higher on the staff means higher in sound. Left to right is time.</div><div class="composer" id="composer"><div class="theory-strip"><span><b>Pitch</b> = high or low</span><span><b>Beat</b> = one steady pulse</span><span><b>Measure</b> = 4 beats here</span></div><div class="staff-wrap"><div class="clef" aria-hidden="true">𝄞</div><div class="staff" id="musicStaff" aria-label="Four-beat music staff">${[0,1,2,3,4].map(i=>`<i style="top:${24+i*16}%"></i>`).join('')}<div class="beat-grid">${[1,2,3,4].map(n=>`<span><small>beat ${n}</small></span>`).join('')}</div>${seed.map((pitch,i)=>`<button class="staff-note" data-step="${i*2}" data-pitch="${pitch}" style="--x:${i*2};--y:${pitchIndex(pitch)}" aria-label="${pitch} on beat ${i+1}"><b>●</b><em>♩</em><small>${pitch}</small></button>`).join('')}</div></div><div class="composer-controls"><button class="lesson-action" id="playLoop">▶ Play loop</button><button class="lesson-action" id="stopLoop">■ Stop</button><button class="lesson-action" id="newNote">+ Add note</button><label>Tempo <input id="tempoRange" type="range" min="60" max="140" value="90"><output id="tempoValue">90</output></label></div><div class="duration-lab"><b>Duration relationship</b><span class="quarter-demo">♩ = 1 beat</span><span class="eighth-demo">♪ + ♪ = 1 beat</span><p>Two half-beat notes occupy the same time as one quarter note—like two halves making one whole.</p></div><p id="musicStatus">Drag a note up or down, then play the loop and listen for the change.</p></div>`}
function spanishTemplate(l){return `<div class="spanish-card"><p class="phrase">${esc(l.data.phrase)}</p><p>${esc(l.data.meaning)}</p><button class="speak-spanish" id="speakSpanish">▶ Escuchar / Listen</button></div>${questionBlock(l.data)}`}
function customTemplate(l){return `<div class="custom-mission"><h3>What to do</h3><p>${esc(l.data.instructions)}</p><label>Portfolio evidence<textarea class="writing-box" id="customEvidence" placeholder="${esc(l.data.prompt)}">${esc(state.drafts[l.id]||'')}</textarea></label><button class="lesson-action" id="saveEvidence">Save evidence</button></div>`}
function pitchIndex(pitch){return ['C5','B4','A4','G4','F4','E4','D4','C4'].indexOf(pitch)}
function bindLesson(){$$('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).close()));$$('.choice[data-answer]').forEach(b=>b.addEventListener('click',()=>{const ok=b.dataset.answer==='true';b.classList.add(ok?'correct':'wrong');$('#answerStatus').textContent=ok?'Correct—now explain why.':'Not yet. Look for the evidence and try again.'}));$$('[data-sound]').forEach(b=>b.addEventListener('click',()=>speakText(b.dataset.sound,.7)));$('#readAloud')?.addEventListener('click',readAloud);$('#stopRead')?.addEventListener('click',stopSpeech);$('#speakSpanish')?.addEventListener('click',()=>speakText(currentLesson.data.phrase,.86,'es-US'));$('#saveDraft')?.addEventListener('click',()=>saveDraftFrom('#writingDraft','Writing sample saved'));$('#saveEvidence')?.addEventListener('click',()=>saveDraftFrom('#customEvidence','Portfolio evidence saved'));$('#checkNumber')?.addEventListener('click',()=>{const ok=Number($('#numberAnswer').value)===currentLesson.data.a;$('#answerStatus').textContent=ok?'Correct. Can you show it with a drawing or equation?':'Try building up or counting back to find the difference.'});$('#testForce')?.addEventListener('click',()=>{const f=Number($('#forceRange').value);window.dispatchEvent(new CustomEvent('starbound:force',{detail:{strength:f}}));$('#forceResult').textContent=`Evidence: strength ${f} moved the sphere ${f*2} distance units. A stronger push caused a larger change in motion.`;$('#answerStatus').textContent='Test complete. What pattern did you observe?'});$('#completeLesson').addEventListener('click',completeLesson);if($('#voiceSelect'))populateVoiceSelect();if($('#musicStaff'))bindComposer()}
function saveDraftFrom(selector,message){state.drafts[currentLesson.id]=$(selector).value.trim();saveState();$('#answerStatus').textContent=`${message} with today's date.`;showToast(message)}
function voiceScore(v,lang){let n=v.name.toLowerCase(),score=v.lang.toLowerCase().startsWith(lang.slice(0,2))?30:0;if(/natural|neural|premium|enhanced|ava|samantha|serena|daniel|google us|google uk/.test(n))score+=20;if(v.localService)score+=4;return score}
function bestVoice(lang='en-US'){return speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith(lang.slice(0,2))).sort((a,b)=>voiceScore(b,lang)-voiceScore(a,lang))[0]||null}
function populateVoiceSelect(){const select=$('#voiceSelect');if(!select)return;const voices=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith('en')).sort((a,b)=>voiceScore(b,'en-US')-voiceScore(a,'en-US')).slice(0,8);select.innerHTML='<option value="auto">Best natural English voice</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${esc(v.lang)})</option>`).join('')}
speechSynthesis.addEventListener?.('voiceschanged',populateVoiceSelect);
function speakText(text,rate=.92,lang='en-US'){stopSpeech();speech=new SpeechSynthesisUtterance(text);speech.rate=rate;speech.pitch=1;speech.lang=lang;const picker=$('#voiceSelect'),chosen=lang.startsWith('en')&&picker&&picker.value!=='auto'?speechSynthesis.getVoices().find(v=>v.voiceURI===picker.value):bestVoice(lang);if(chosen)speech.voice=chosen;speechSynthesis.speak(speech)}
function playTone(freq,duration=.3,delay=0){const audio=playTone.ctx||(playTone.ctx=new(window.AudioContext||window.webkitAudioContext)());const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(0,audio.currentTime+delay);gain.gain.linearRampToValueAtTime(.2,audio.currentTime+delay+.02);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+delay+duration);osc.connect(gain).connect(audio.destination);osc.start(audio.currentTime+delay);osc.stop(audio.currentTime+delay+duration);window.dispatchEvent(new CustomEvent('starbound:note',{detail:{frequency:freq,delay}}))}
function playPattern(){const beats=$$('.beat').map(b=>b.classList.contains('on'));beats.forEach((on,i)=>{if(on)playTone([261.63,329.63,392,523.25][i],.25,i*.42)});$('#answerStatus').textContent='You created and performed a rhythm pattern.'}
let loopTimer=null,noteTimers=[];
const PITCHES=['C5','B4','A4','G4','F4','E4','D4','C4'],FREQ={C4:261.63,D4:293.66,E4:329.63,F4:349.23,G4:392,A4:440,B4:493.88,C5:523.25};
function setNote(note,step,pitchIndexValue){const y=Math.max(0,Math.min(7,pitchIndexValue)),x=Math.max(0,Math.min(7,step));note.dataset.step=x;note.dataset.pitch=PITCHES[y];note.style.setProperty('--x',x);note.style.setProperty('--y',y);note.querySelector('small').textContent=PITCHES[y];note.setAttribute('aria-label',`${PITCHES[y]} at ${x/2+1} beats`)}
function playComposition(loop=false){stopComposition();const tempo=Number($('#tempoRange')?.value||90),halfBeat=30000/tempo,notes=$$('.staff-note').sort((a,b)=>Number(a.dataset.step)-Number(b.dataset.step));const run=()=>{notes.forEach(n=>noteTimers.push(setTimeout(()=>{n.classList.add('playing');playTone(FREQ[n.dataset.pitch],halfBeat/1000*.85);setTimeout(()=>n.classList.remove('playing'),halfBeat*.75)},Number(n.dataset.step)*halfBeat)))};run();if(loop)loopTimer=setInterval(run,halfBeat*8);$('#musicStatus').textContent=`Playing ${notes.length} notes at ${tempo} beats per minute. Listen for high, low, and repeated pitches.`}
function stopComposition(){if(loopTimer)clearInterval(loopTimer);loopTimer=null;noteTimers.forEach(clearTimeout);noteTimers=[];$$('.staff-note').forEach(n=>n.classList.remove('playing'))}
function bindComposer(){const staff=$('#musicStaff');let drag=null;const move=(e,n)=>{const r=staff.getBoundingClientRect(),x=Math.round(Math.max(0,Math.min(.99,(e.clientX-r.left)/r.width))*7),y=Math.round(Math.max(0,Math.min(.99,(e.clientY-r.top)/r.height))*7);setNote(n,x,y);$('#musicStatus').textContent=`${n.dataset.pitch}: ${PITCHES.indexOf(n.dataset.pitch)<4?'higher':'lower'} pitch, placed at beat ${(x/2+1).toFixed(1)}.`};const wire=n=>{n.addEventListener('pointerdown',e=>{drag=n;n.setPointerCapture(e.pointerId)});n.addEventListener('pointermove',e=>{if(drag===n)move(e,n)});n.addEventListener('pointerup',e=>{move(e,n);drag=null;playTone(FREQ[n.dataset.pitch],.3)});n.addEventListener('keydown',e=>{let x=Number(n.dataset.step),y=PITCHES.indexOf(n.dataset.pitch);if(e.key==='ArrowUp')y--;else if(e.key==='ArrowDown')y++;else if(e.key==='ArrowLeft')x--;else if(e.key==='ArrowRight')x++;else return;e.preventDefault();setNote(n,x,y);playTone(FREQ[n.dataset.pitch],.2)})};$$('.staff-note').forEach(wire);$('#playLoop').addEventListener('click',()=>playComposition(true));$('#stopLoop').addEventListener('click',()=>{stopComposition();$('#musicStatus').textContent='Loop stopped. Change a note and compare the new pattern.'});$('#newNote').addEventListener('click',()=>{const n=document.createElement('button');n.className='staff-note';n.innerHTML='<b>●</b><em>♪</em><small>E4</small>';setNote(n,1,5);staff.appendChild(n);wire(n);$('#musicStatus').textContent='Added an eighth-note sound halfway through beat 1.'});$('#tempoRange').addEventListener('input',e=>{$('#tempoValue').textContent=e.target.value;$('#musicStatus').textContent=`Tempo is ${e.target.value} beats per minute. Higher numbers make the same pattern go faster.`})}
function readAloud(){const el=$('#readerText'),text=el.dataset.plain;stopSpeech();speech=new SpeechSynthesisUtterance(text);speech.rate=.92;speech.pitch=1;const selected=$('#voiceSelect')?.value,chosen=selected&&selected!=='auto'?speechSynthesis.getVoices().find(v=>v.voiceURI===selected):bestVoice('en-US');if(chosen)speech.voice=chosen;speech.onboundary=e=>{const spans=$$('#readerText span');spans.forEach(s=>s.classList.remove('speaking'));let chars=0;for(const span of spans){chars+=span.textContent.length+1;if(chars>e.charIndex){span.classList.add('speaking');break}}};speech.onend=()=>$$('#readerText span').forEach(s=>s.classList.remove('speaking'));speechSynthesis.speak(speech)}
function stopSpeech(){speechSynthesis.cancel();speech=null}
function completeLesson(){const l=currentLesson;if(!state.progress.some(p=>p.learner===state.current&&p.lessonId===l.id)){state.progress.unshift({id:crypto.randomUUID(),learner:state.current,subject:currentSubject,lessonId:l.id,title:l.title,skill:l.skill,date:new Date().toISOString(),kind:'mission'});saveState()}stopSpeech();stopComposition();$('#lessonDialog').close();updateHeader();openSubject(currentSubject);showToast(`Mission logged for ${new Date().toLocaleDateString()} — star earned!`)}
function statsFor(entries){return Object.keys(SUBJECTS).map(s=>({s,n:entries.filter(e=>e.subject===s).length}))}
function renderLog(){const all=[...state.progress,...state.entries].sort((a,b)=>new Date(b.date)-new Date(a.date));const learner=$('#logLearner').value,subject=$('#logSubject').value;const visible=all.filter(e=>(learner==='all'||e.learner===learner)&&(subject==='all'||e.subject===subject));$('#summaryStats').innerHTML=statsFor(all).map(x=>`<div class="stat" style="--accent:${SUBJECTS[x.s].color}"><strong>${x.n}</strong><span>${SUBJECTS[x.s].kicker} records</span></div>`).join('');$('#activityLog').innerHTML=visible.length?visible.map(e=>`<div class="log-row"><time>${new Date(e.date).toLocaleDateString()}</time><span class="subject-pill">${e.subject}</span><div><b>${esc(e.title||'Family learning note')}</b><p>${esc(e.note||e.skill||'')}</p></div><small>${e.learner}</small></div>`).join(''):'<div class="empty">No records match these filters yet.</div>'}
$('#logLearner').addEventListener('change',renderLog);$('#logSubject').addEventListener('change',renderLog);$('#addEntryBtn').addEventListener('click',()=>{$('#entryForm [name=learner]').value=state.current;$('#entryDialog').showModal()});$('#entryForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);state.entries.unshift({id:crypto.randomUUID(),learner:d.get('learner'),subject:d.get('subject'),title:'Family learning note',note:d.get('note'),skill:d.get('skills'),date:new Date().toISOString(),kind:'note'});saveState();e.target.reset();$('#entryDialog').close();renderLog();showToast('Learning note saved')});
$('#planLessonBtn').addEventListener('click',()=>{$('#planForm [name=learner]').value=state.current;$('#planDialog').showModal()});$('#planForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target),lesson={id:`custom-${crypto.randomUUID()}`,learner:d.get('learner'),subject:d.get('subject'),title:d.get('title'),desc:d.get('skill'),skill:d.get('skill'),type:'custom',createdAt:new Date().toISOString(),data:{instructions:d.get('instructions'),prompt:d.get('prompt')}};state.customLessons.push(lesson);saveState();e.target.reset();$('#planDialog').close();showToast(`New ${SUBJECTS[lesson.subject].kicker} mission added for ${lesson.learner}`);if(state.current===lesson.learner)openSubject(lesson.subject)});
function renderPortfolio(){const who=state.portfolio;$$('[data-portfolio]').forEach(b=>b.classList.toggle('selected',b.dataset.portfolio===who));const records=[...state.progress,...state.entries].filter(e=>e.learner===who).sort((a,b)=>new Date(a.date)-new Date(b.date));const lessonDefs=[...Object.values(LESSONS[who]).flat(),...state.customLessons.filter(l=>l.learner===who)];const sections=Object.keys(SUBJECTS).map(subject=>{const r=records.filter(e=>e.subject===subject),subjectDefs=lessonDefs.filter(l=>(LESSONS[who][subject]||[]).includes(l)||l.subject===subject);const samples=Object.entries(state.drafts).filter(([id,v])=>v&&subjectDefs.some(l=>l.id===id)).map(([id,text])=>{const l=lessonDefs.find(x=>x.id===id),done=records.find(x=>x.lessonId===id);return `<div class="work-sample"><b>${esc(l?.title||'Work sample')}</b><small>${done?`Completed ${new Date(done.date).toLocaleDateString()}`:'Saved work in progress'}</small>\n${esc(text)}</div>`}).join('');return `<section class="portfolio-section"><h3>${SUBJECTS[subject].glyph} ${SUBJECTS[subject].kicker}</h3><p><b>${r.length} documented learning ${r.length===1?'experience':'experiences'}</b></p>${r.slice(-8).map(e=>`<div class="work-sample"><b>${esc(e.title||'Learning note')}</b><small>Completed ${new Date(e.date).toLocaleDateString()}</small>\n${esc(e.note||e.skill||'')}</div>`).join('')}${samples||(!r.length?'<p class="empty">Future work will appear here.</p>':'')}</section>`}).join('');$('#portfolioPaper').innerHTML=`<header class="portfolio-cover"><div><p>Starbound Academy</p><h2>${who}'s learning portfolio</h2><p>2026–2027 · Updated ${new Date().toLocaleDateString()}</p></div><div><b>${records.length}</b><br>dated experiences</div></header><section class="portfolio-section"><h3>Learning story</h3><p>${who} is building a dated record of reading, writing, mathematical reasoning, scientific investigation, music, and Spanish. This portfolio includes completed digital missions, saved work, and family observations.</p></section>${sections}`}
$$('[data-portfolio]').forEach(b=>b.addEventListener('click',()=>{state.portfolio=b.dataset.portfolio;saveState();renderPortfolio()}));$('#printBtn').addEventListener('click',()=>window.print());
$('#exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`starbound-academy-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)});$('#importInput').addEventListener('change',async e=>{try{const data=JSON.parse(await e.target.files[0].text());state={...defaultState,...data};saveState();updateHeader();renderLog();showToast('Backup imported')}catch{showToast('That backup could not be read.')}});
updateHeader();renderPortfolio();if(!localStorage.getItem('starbound-welcomed')){$('#profileDialog').showModal();localStorage.setItem('starbound-welcomed','yes')}
